<section class="admin-head"><div><p class="kicker">PIM taxonomy</p><h1>Taxonomies</h1><p>Shared values keep product data consistent across the catalogue.</p></div></section><form class="taxonomy-form" method="post" action="<?=e(url('/admin/taxonomies'))?>"><?=csrf_field()?>
